# Test various predictabilities
def corr(a,b):
    m = np.isfinite(a) & np.isfinite(b)
    if np.sum(m)<30:
        return 0.0
    a=a[m]; b=b[m]
    if np.std(a)<1e-9 or np.std(b)<1e-9:
        return 0.0
    return float(np.corrcoef(a,b)[0,1])

H_mid = {k: np.array(H[k]['mid'],dtype=float) for k in H}
H_imb = {k: np.array(H[k]['imbalance'],dtype=float) for k in H}
H_sv = {k: np.array(H[k]['signed_volume'],dtype=float) for k in H}

res={}
# 1. IDX basket premium
basket = 0.3333*H_mid['A'] + 0.6667*H_mid['B'] + 0.1667*H_mid['C']
idx = H_mid['IDX']
premium = idx - basket
res['premium_mean'] = float(np.nanmean(premium))
res['premium_std'] = float(np.nanstd(premium))
res['premium_range'] = [float(np.nanmin(premium)), float(np.nanmax(premium))]
if len(premium)>20:
    res['premium_autocorr_1'] = corr(premium[:-1], premium[1:])
    res['premium_autocorr_10'] = corr(premium[:-10], premium[10:])
for horizon in [10,30,50,100]:
    if len(premium)>horizon+10:
        fut_idx_ret = (np.roll(idx,-horizon)-idx)/idx
        fut_basket_ret = (np.roll(basket,-horizon)-basket)/basket
        valid = np.isfinite(premium) & np.isfinite(fut_idx_ret)
        valid[-horizon:]=False
        if np.sum(valid)>50:
            res['premium_vs_idx_minus_basket_'+str(horizon)] = corr(premium[valid], (fut_idx_ret - fut_basket_ret)[valid])
            res['premium_vs_minus_premium_change_'+str(horizon)] = corr(premium[valid], -(np.roll(premium,-horizon)-premium)[valid])

# 2. Cross-exchange gaps
for base in ['A','B','C']:
    alt = base+'.X'
    gap = H_mid[base] - H_mid[alt]
    res[base+'_gap_mean'] = float(np.nanmean(gap))
    res[base+'_gap_std'] = float(np.nanstd(gap))
    res[base+'_gap_autocorr1'] = corr(gap[:-1], gap[1:])
    for h in [10,30,50]:
        fut_gap_change = np.roll(gap,-h)-gap
        valid = np.isfinite(gap) & np.isfinite(fut_gap_change)
        valid[-h:]=False
        if np.sum(valid)>50:
            res[base+'_gap_revert_'+str(h)] = corr(gap[valid], -fut_gap_change[valid])
            fut_ret_base = (np.roll(H_mid[base],-h)-H_mid[base])/H_mid[base]
            fut_ret_alt = (np.roll(H_mid[alt],-h)-H_mid[alt])/H_mid[alt]
            res[base+'_gap_vs_retDiff_'+str(h)] = corr(gap[valid], (fut_ret_alt - fut_ret_base)[valid])

result=res

def signal(obs):
    # premium mean reversion with rolling zscore
    def get_mid(asset, n=1):
        arr = obs.hist(asset,'mid',n)
        if arr is None or len(arr)==0:
            return None
        v = arr[-1]
        if v != v: # NaN
            return None
        return float(v)
    # need at least 200 steps history
    mA = obs.hist('A','mid',200)
    mB = obs.hist('B','mid',200)
    mC = obs.hist('C','mid',200)
    mIDX = obs.hist('IDX','mid',200)
    if mA is None or mB is None or mC is None or mIDX is None:
        return {}
    if len(mA)<200 or len(mB)<200 or len(mC)<200 or len(mIDX)<200:
        return {}
    # handle NaNs
    if not (np.isfinite(mA[-1]) and np.isfinite(mB[-1]) and np.isfinite(mC[-1]) and np.isfinite(mIDX[-1])):
        return {}
    basket = 0.3333*mA + 0.6667*mB + 0.1667*mC
    premium = mIDX - basket
    # compute mean/std ignoring NaNs
    valid = np.isfinite(premium)
    if np.sum(valid)<150:
        return {}
    mean = np.nanmean(premium)
    std = np.nanstd(premium)
    if std<1e-6 or not np.isfinite(std):
        return {}
    z = (premium[-1] - mean)/std
    # threshold
    # scale to target [-1,1]
    # clip z to [-3,3], then linear
    zc = max(min(z, 3), -3)
    # target magnitude 0.7 * (zc/3) but only trade if |z|>0.5 to avoid noise? Let's trade proportionally
    strength = zc/3.0  # -1 to 1 when z= +/-3
    # dead zone
    if abs(strength)<0.1:
        strength=0
    # IDX opposite, basket legs with weights
    sig_IDX = -strength * 0.9
    sig_A = strength * 0.9 * 0.3333 * 2.0  # boost to match notional? try factor 1
    sig_B = strength * 0.9 * 0.6667 * 2.0
    sig_C = strength * 0.9 * 0.1667 * 2.0
    # clip to [-1,1]
    def clip(x): return max(min(x,1),-1)
    return {'IDX': clip(sig_IDX), 'A': clip(sig_A), 'B': clip(sig_B), 'C': clip(sig_C)}

def signal(obs):
    st = obs.state
    if 'pos' not in st:
        st['pos'] = {'IDX':0,'A':0,'B':0,'C':0}
        st['hold'] = 0  # steps held
        st['cooldown'] = 0
    def get(arr_asset, n):
        try:
            h = obs.hist(arr_asset,'mid',n)
        except:
            return None
        return h
    W = 100
    N = 120
    hA = get('A', N)
    hB = get('B', N)
    hC = get('C', N)
    hI = get('IDX', N)
    if hA is None or hB is None or hC is None or hI is None:
        return {}
    if len(hA)<W or len(hB)<W or len(hC)<W or len(hI)<W:
        return {}
    if not (np.isfinite(hA[-1]) and np.isfinite(hB[-1]) and np.isfinite(hC[-1]) and np.isfinite(hI[-1])):
        return {}
    basket = 0.3333*hA + 0.6667*hB + 0.1667*hC
    prem = hI - basket
    if not np.isfinite(prem[-1]):
        return {}
    # track hold counter
    # if we are in position, increment hold
    in_pos = abs(st['pos']['IDX'])>0.05
    if in_pos:
        st['hold'] += 10  # called every 10 steps
        st['cooldown'] = 0
    else:
        if st['cooldown']>0:
            st['cooldown'] -= 10
        st['hold']=0
    out = {}
    # entry only if flat and not in cooldown
    if not in_pos and st['cooldown']<=0:
        # use recent premium level directly, not z, to exploit asymmetry
        # entry threshold -11.5 ~ spread cost 11.3 plus 0.2 buffer
        if prem[-1] < -12.0:
            # also require that premium is below its recent mean to avoid buying in uptrend? check mean
            # compute recent mean/std for confirmation but threshold is absolute
            # need sufficient history to ensure not NaN
            recent = prem[-W:]
            valid = np.isfinite(recent)
            if np.sum(valid)>=80:
                mean = np.mean(recent[valid])
                # only enter if premium is still below mean (cheap relative to recent)
                if prem[-1] < mean:
                    # enter long IDX short basket
                    # scale 0.6 to stay within limits and allow hedged notional ~1:1
                    out['IDX'] = 0.6
                    out['A'] = -0.2  # 0.6*0.333
                    out['B'] = -0.4  # 0.6*0.666
                    out['C'] = -0.1  # 0.6*0.166
                    st['pos'] = {'IDX':0.6,'A':-0.2,'B':-0.4,'C':-0.1}
                    st['hold']=0
                    return out
        # no entry => stay flat (do not send)
        return {}
    elif in_pos:
        # exit conditions: hold at least 120 steps (12 calls) to capture reversion and reduce turnover
        # exit if premium reverted above -3 (near fair) or hold >150 steps or premium turned positive
        if st['hold'] >= 140:  # 14 calls *10 =140
            # time exit
            out['IDX']=0.0
            out['A']=0.0
            out['B']=0.0
            out['C']=0.0
            st['pos']={'IDX':0,'A':0,'B':0,'C':0}
            st['cooldown']=30
            return out
        if prem[-1] > -3.0:
            out['IDX']=0.0
            out['A']=0.0
            out['B']=0.0
            out['C']=0.0
            st['pos']={'IDX':0,'A':0,'B':0,'C':0}
            st['cooldown']=30
            return out
        # otherwise hold - return empty to keep position
        return {}
    return {}

