def signal(obs):
    h = obs.hist('B', 'mid', 115)
    if h.shape[0] < 105:
        return {}
    cur = float(h[-1])
    old = float(h[-101])
    if not (cur == cur and old == old):
        return {}
    past = cur - old
    if past < -6.0:
        return {'B': 1.0}
    elif past > 6.0:
        return {'B': -1.0}
    return {}

def signal(obs):
    try:
        hi = obs.hist('IDX', 'mid', 320)
        ha = obs.hist('A', 'mid', 320)
        hb = obs.hist('B', 'mid', 320)
        hc = obs.hist('C', 'mid', 320)
    except Exception:
        return {}
    n = hi.shape[0]
    if n < 310:
        return {}
    nav = 0.3333*ha + 0.6667*hb + 0.1667*hc
    gap = hi - nav
    g = gap[np.isfinite(gap)]
    if g.shape[0] < 200:
        return {}
    mu = float(np.mean(g[-200:]))
    cur = float(g[-1])
    if not (cur == cur and mu == mu):
        return {}
    dev = cur - mu
    if dev < -8.0:
        return {'IDX': 1.0, 'A': -0.3333, 'B': -0.6667, 'C': -0.1667}
    elif dev > 8.0:
        return {'IDX': -1.0, 'A': 0.3333, 'B': 0.6667, 'C': 0.1667}
    return {}

