def corr(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    a=a[m]; b=b[m]
    if len(a)<40: return 0.0
    sa=float(np.std(a)); sb=float(np.std(b))
    if sa<1e-9 or sb<1e-9: return 0.0
    return float(np.mean((a-np.mean(a))*(b-np.mean(b)))/sa/sb)
