            fut = mid[i+lb+horizon]-mid[i+lb]
            if not math.isnan(fut):
                rets.append(fut)
                sigs.append(ret_lb)
    if len(rets)<100:
        return float('nan')
    # spearman approx pearson
    import math as m
    # pearson
    sm = sum(sigs)/len(sigs)
    rm = sum(rets)/len(rets)
    num=0; ds=0; dr=0
    for s,r in zip(sigs,rets):
        num+=(s-sm)*(r-rm)
        ds+=(s-sm)**2
        dr+=(r-rm)**2
    if ds==0 or dr==0:
        return 0
    return num/math.sqrt(ds*dr)

