def pearson(x,y):
    n=len(x)
    if n<30:
        return float('nan')
    mx=sum(x)/n; my=sum(y)/n
    num=0.0; dx=0.0; dy=0.0
    for i in range(n):
        a=x[i]-mx; b=y[i]-my
        num+=a*b; dx+=a*a; dy+=b*b
    if dx<=1e-9 or dy<=1e-9:
        return 0.0
    return num/math.sqrt(dx*dy)

