    if not (sd > 1e-9):
        return {}
    syn = 0.3333*mA+0.6667*mB+0.1667*mC
    d = mI - syn
    if not (d == d):
        return {}
    z = (d-mu)/sd
    thr = 0.5
    if abs(z) < thr:
        pos = 0.0
    else:
        pos = -z/3.0
        if pos > 1.0: pos = 1.0
