    targets={}
    # IDX basket arbitrage with wider lookback and static threshold learned: 100c approx 0.8 std? Actually std ~125, threshold 100 ~0.8
    # Use rolling z 1.0
    # Avoid overlapping with A-A.X hedges: prioritize IDX arb, so only do A.X arb if IDX not active
    # EstimateBasket

    def get_spread(hist_len=200):
        mA = obs.hist('A','mid',hist_len)
        mB = obs.hist('B','mid',hist_len)
        mC = obs.hist('C','mid',hist_len)
        mIDX = obs.hist('IDX','mid',hist_len)
        if mA is None or mB is None or mC is None or mIDX is None or len(mA)<hist_len:
            return None, None, None
        spreads=[]
        for i in range(hist_len):
            if mA[i]==mA[i] and mB[i]==mB[i] and mC[i]==mC[i] and mIDX[i]==mIDX[i]:
                b=0.3333*mA[i]+0.6667*mB[i]+0.1667*mC[i]
                spreads.append(mIDX[i]-b)
            else:
                spreads.append(float('nan'))
        vals=[x for x in spreads if x==x]
        if len(vals)<80:
            return None, None, None
        mean=sum(vals)/len(vals)
        var=sum((x-mean)**2 for x in vals)/len(vals)
        std=math.sqrt(var) if var>1e-9 else 80
        cur=spreads[-1]
        if cur!=cur:
            return None, None, None
        # adaptive but clamp
        if std<30:
            std=30
        if std>200:
            std=200
        z=(cur-mean)/std
        return z, mean, std

    z,_,_ = get_spread(200)
