            # Keep hedge small to reduce turnover? Test both. Start pure IDX.
        elif z < -1.0:
            targets['IDX']=1.0
        elif abs(z) < 0.4:
            targets['IDX']=0.0

    # A-A.X pair with similar z but only if IDX not signaling strongly to avoid conflicting A direction
