        mA = obs.hist('A','mid',100)
        mAX = obs.hist('A.X','mid',100)
        if mA is not None and mAX is not None and len(mA)>=100:
            s=[mA[i]-mAX[i] if mA[i]==mA[i] and mAX[i]==mAX[i] else float('nan') for i in range(100)]
            vals=[x for x in s if x==x]
