    targets={}
    # IDX arb simple fixed threshold 90
    mA = obs.last('A','mid')
    mB = obs.last('B','mid')
    mC = obs.last('C','mid')
    mIDX = obs.last('IDX','mid')
    if mA==mA and mB==mB and mC==mC and mIDX==mIDX:
        b=0.3333*mA+0.6667*mB+0.1667*mC
        spr=mIDX-b
        if spr > 90:
            targets['IDX']=-1.0
            targets['A']=0.5
            targets['B']=1.0
            targets['C']=0.3
        elif spr < -90:
            targets['IDX']=1.0
            targets['A']=-0.5
            targets['B']=-1.0
            targets['C']=-0.3
        elif abs(spr)<30:
            targets['IDX']=0.0
            # need to avoid zeroing A/B/C if momentum wants them; so only zero if momentum not active later? We'll let momentum overwrite
            targets['A']=0.0
            targets['B']=0.0
            targets['C']=0.0
    # Momentum on A/C/X using lb30 (more stable recent) with threshold 0.85
    # Use vol-normalized zscore as earlier but simplified with fixed vol estimation from hist
    def mom_signal(asset, lb, thresh=0.85):
        m = obs.last(asset,'mid')
        hist = obs.hist(asset,'mid', lb+1)
        if hist is None or len(hist) < lb+1 or m!=m or hist[0]!=hist[0]:
            return None
        ret = m - hist[0]
        h = obs.hist(asset,'mid', 70)
        if h is None or len(h)<20:
            vol=2.0
        else:
            s=0.0
            s2=0.0
            n=0
            for i in range(1,len(h)):
                a=h[i]
                b=h[i-1]
                if a==a and b==b:
                    d=a-b
                    s+=d
                    s2+=d*d
                    n+=1
            if n<10:
                vol=2.0
            else:
                mean=s/n
                var=s2/n - mean*mean
                if var<0:
                    var=0
                vol=math.sqrt(var) if var>1e-9 else 2.0
                if vol<0.6:
                    vol=0.6
                if vol>10:
                    vol=10
        z=ret/(vol*math.sqrt(lb)) if vol>0 else 0
