def mom_slice_detail(asset, lb, th_z):
    mid=H[asset]['mid']
    n=len(mid)
    # calc vol overall
    diffs=[mid[i]-mid[i-1] for i in range(1,n) if mid[i]==mid[i] and mid[i-1]==mid[i-1]]
    m=sum(diffs)/len(diffs)
    vol=math.sqrt(sum((x-m)**2 for x in diffs)/len(diffs))
    th=th_z*vol*math.sqrt(lb)
    # per slice pnl gross mid
    def pnl_range(s,e):
        pnl=0
        cnt=0
        for i in range(s+lb, e-50, 10):
            if mid[i]!=mid[i] or mid[i-lb]!=mid[i-lb] or mid[i+50]!=mid[i+50]:
                continue
            ret=mid[i]-mid[i-lb]
            fwd=mid[i+50]-mid[i]
            if ret>th:
                pnl+=fwd
                cnt+=1
            elif ret<-th:
                pnl+=-fwd
                cnt+=1
        return pnl,cnt
    result={}
    for name,s,e in [('first',0,3375),('second',3375,6750),('recent750',6000,6750)]:
        p,c=pnl_range(s,e)
        result[name]=f"{round(p)}/{c}"
    return result

